+  const STATES: readonly FileFlowState[] = [
+    { kind: 'idle' },
+    { kind: 'acquiring', name: 'a.arq' },
+    { kind: 'detecting', name: 'a.arq' },
+    { kind: 'native-opening', name: 'a.arq', sidecarDependency: 'complete' },
