+    }
+    if (role === 'unknown') {
+      unknownMismatches.push(path);
+      continue;
+    }
+    // A canonical entry that is absent entirely and one whose bytes changed are
+    // different repairs - regenerate versus restore - so they are reported
+    // apart even though both are fatal.
