+      if (expected !== undefined && (typeof expected !== 'number' || !Number.isInteger(expected))) {
+        return null;
+      }
+      return {
+        id,
+        type: 'publish',
+        targetName: candidate['targetName'],
+        ...(expected === undefined ? {} : { expectedRevision: expected }),
+      };
+    }
