+    expect(parsed('250mm')).toEqual({ value: 250, unit: 'mm' });
+    expect(parsed('12.5cm')).toEqual({ value: 12.5, unit: 'cm' });
+    expect(parsed('18in')).toEqual({ value: 18, unit: 'in' });
