+  });
+
+  it('rejects a non-positive scale', () => {
+    expect(checkCropFits(CROP, 0, SHEET_WIDTH, SHEET_HEIGHT)).toBe(
+      VIEWPORT_REJECTIONS.invalidScale,
+    );
+  });
