+    const verdict = feed(guard, RATIO_CHECK_FLOOR_BYTES + 1024);
+
+    expect(verdict.status).toBe('refused');
+    if (verdict.status !== 'refused') return;
+    expect(verdict.code).toBe(DECOMPRESSION_REFUSAL_CODES.ratioTooHigh);
+  });
