+    const verdict = guard.accept(1);
+
+    expect(verdict.status).toBe('refused');
+    if (verdict.status !== 'refused') return;
+    expect(verdict.code).toBe(DECOMPRESSION_REFUSAL_CODES.emptyInput);
+  });
