+    // giving it a specific code would claim otherwise.
+    expect(importRejectionCode(new Error('who knows'), 'FALLBACK')).toBe('FALLBACK');
+    expect(importRejectionCode('a string', 'FALLBACK')).toBe('FALLBACK');
+  });
