+    type: 'convert',
+    requestId,
+    bytes,
+    source: source as InputFileDescriptor,
+    ...(expected === undefined ? {} : { expectedSourceSha256: expected }),
+    formatId: candidate['formatId'],
+    adapterId: candidate['adapterId'],
+    policy: policy as SerializableImportPolicy,
+  };
